createLabel('Pinhole', () => new THREE.Vector3(0, -0.2, 0), '3d', 'world', { offset: [0, 15] });
createLabel('(0,0,0)', () => new THREE.Vector3(-0.1, 0.1, 0), '3d', 'world', { offset: [-25, -10] });

