createLabel('<b>p</b>', () => virtGroup.position.clone().add(pVirt.position), '3d', 'virt', { offset: [12, -12], fontSize: '15px' });
createLabel('<i>x</i>', () => virtGroup.position.clone().add(new THREE.Vector3(2.2, 0, 0)), '3d', 'virt', { offset: [0, 10], color: '#009900' });
createLabel('<i>y</i>', () => virtGroup.position.clone().add(new THREE.Vector3(0, 2.2, 0)), '3d', 'virt', { offset: [-10, 0], color: '#009900' });

createLabel('Projection plane', () => new THREE.Vector3(0, -2.6, physGroup.position.z), '3d', 'phys', { offset: [0, 10] });
createLabel('<i>f</i>', () => new THREE.Vector3(0, 0.1, physGroup.position.z / 2), '3d', 'phys', { offset: [10, -10], color: '#cc0000' });
createLabel('<b>p</b>', () => physGroup.position.clone().add(pPhys.position), '3d', 'phys', { offset: [-12, 12], fontSize: '15px' });
createLabel('<i>x</i>', () => physGroup.position.clone().add(new THREE.Vector3(-2.2, 0, 0)), '3d', 'phys', { offset: [0, 10], color: '#009900' });
createLabel('<i>y</i>', () => physGroup.position.clone().add(new THREE.Vector3(0, -2.2, 0)), '3d', 'phys', { offset: [10, 0], color: '#009900' });

// 2D Text
createLabel('Camera coordinates', () => new THREE.Vector3(1.5, 1.5, 0), '2d', '2d', { offset: [0, -20], color: '#009900' });
createLabel('Image coordinates', () => new THREE.Vector3(-1.5, -2.2, 0), '2d', '2d', { offset: [0, -10], color: '#0000cc' });
createLabel('<i>x</i>', () => new THREE.Vector3(1.6, 0, 0), '2d', '2d', { offset: [-10, 15], color: '#009900' });
createLabel('<i>y</i>', () => new THREE.Vector3(0, 1.6, 0), '2d', '2d', { offset: [15, 0], color: '#009900' });
createLabel('<i>n</i>', () => new THREE.Vector3(-1.4, -2.4, 0), '2d', '2d', { offset: [0, 15], color: '#0000cc' });
createLabel('<i>m</i>', () => new THREE.Vector3(-3, -0.8, 0), '2d', '2d', { offset: [15, 0], color: '#0000cc' });
createLabel('(0,0)', () => new THREE.Vector3(-3, -2.4, 0), '2d', '2d', { offset: [-20, 15], color: '#0000cc' });
createLabel('(0,0)', () => new THREE.Vector3(0, 0, 0), '2d', '2d', { offset: [20, 15], color: '#009900' });
