function updatePositions() {
    const fVal = parseFloat(document.getElementById('slider-f').value);

    virtGroup.position.set(0, 0, fVal);
    physGroup.position.set(0, 0, -fVal);
    arrowFvirt.setLength(fVal, 0.3, 0.15);
    arrowFphys.setLength(fVal, 0.3, 0.15);

    const Z = pointP.position.z;
    const px = Z !== 0 ? (fVal * pointP.position.x / Z) : 0;
    const py = Z !== 0 ? (fVal * pointP.position.y / Z) : 0;

    pVirt.position.set(px, py, 0);
    pPhys.position.set(-px, -py, 0);
    p2d.position.set(px, py, 0.01);

    const projMode = document.getElementById('select-proj').value;
    const endPt = new THREE.Vector3();
    if (projMode === 'both' || projMode === 'physical') {
        endPt.set(-px, -py, -fVal);
    } else {
        endPt.set(0, 0, 0);
    }
    rayLine.geometry.setFromPoints([pointP.position, endPt]);
    rayLine.computeLineDistances();

    updateLabels();
}

function updateVisibility() {
    const view = document.getElementById('select-view').value;
    const projMode = document.getElementById('select-proj').value;

    if (view === '2d') {
        group3D.visible = false;
        group2D.visible = true;
    } else {
        group3D.visible = true;
        group2D.visible = false;
        virtGroup.visible = (projMode === 'both' || projMode === 'virtual');
        physGroup.visible = (projMode === 'both' || projMode === 'physical');
        arrowFvirt.visible = virtGroup.visible;
        arrowFphys.visible = physGroup.visible;
        rayLine.visible = true;
    }
}

function updateLabels() {
    const view = document.getElementById('select-view').value;
    const projMode = document.getElementById('select-proj').value;

    labels3D.forEach(obj => {
        let isVisible = false;
        if (view === '3d') {
            if (obj.groupTag === 'virt') isVisible = (projMode === 'both' || projMode === 'virtual');
            else if (obj.groupTag === 'phys') isVisible = (projMode === 'both' || projMode === 'physical');
            else isVisible = true;
        }
        obj.lbl.div.style.display = isVisible ? '' : 'none';
        if (isVisible) obj.lbl.pos.copy(obj.posFn());
    });

    labels2D.forEach(obj => {
        const isVisible = (view === '2d');
        obj.lbl.div.style.display = isVisible ? '' : 'none';
        if (isVisible) obj.lbl.pos.copy(obj.posFn());
    });
}

