// @FIGURE_CODE_BEGIN
// 1. World axes (Z, Y, X) -> ArrowHelpers on Three.js (X, Y, -Z). Z is optical axis.
// 2. Pinhole -> SphereGeometry(0.08) black
// 3. Point P -> SphereGeometry(0.15) light blue with dark outline
// 4. Reference Lines for P -> Dashed lines dropping to XZ plane and then primary axis
// 5. Virtual Plane (X=f) -> PlaneGeometry(6, 4.8) semi-transparent light gray
// 6. Physical Plane (X=-f) -> PlaneGeometry(6, 4.8) semi-transparent dark gray with dashed edges
// 7. Projection Ray -> Line(dashed grey)
// 8. Focal length f -> ArrowHelpers(red), offset from axis
// 9. 2D Sensor view -> PlaneGeometry(6, 4.8) white with black edge at Y=100
// 10. Camera & Image axes -> ArrowHelpers(green and blue) in 2D view

const group3D = new THREE.Group();
const group2D = new THREE.Group();
group2D.position.set(0, 100, 0);
scene.add(group3D);
scene.add(group2D);
group2D.visible = false;

// --- 3D Scene Elements ---
const pinhole = new THREE.Mesh(
    new THREE.SphereGeometry(0.08, 16, 16), 
    new THREE.MeshBasicMaterial({color: 0x000000})
);
group3D.add(pinhole);

// Map Textbook (Z, Y, X) to Three.js (X, Y, -Z)
// Textbook Z (Optical Axis) is Three.js +X
const arrowZ_world = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(0,0,0), 8.5, 0x000000, 0.25, 0.15);
// Textbook Y (Vertical) is Three.js +Y
const arrowY_world = new THREE.ArrowHelper(new THREE.Vector3(0,1,0), new THREE.Vector3(0,0,0), 4.5, 0x000000, 0.25, 0.15);
// Textbook X (Depth) is Three.js -Z
const arrowX_world = new THREE.ArrowHelper(new THREE.Vector3(0,0,-1), new THREE.Vector3(0,0,0), 4.5, 0x000000, 0.25, 0.15);
group3D.add(arrowZ_world, arrowY_world, arrowX_world);

const pGeom = new THREE.SphereGeometry(0.15, 32, 32);
const pMat = new THREE.MeshBasicMaterial({color: 0x66ccff});
const pointP = new THREE.Mesh(pGeom, pMat);
const pOutline = new THREE.Mesh(pGeom, new THREE.MeshBasicMaterial({color: 0x222222, side: THREE.BackSide}));
pOutline.scale.setScalar(1.15);
pointP.add(pOutline);
// Initial P: Textbook Z=7, Y=2.5, X=2 (into page) -> Three.js (7, 2.5, -2)
pointP.position.set(7, 2.5, -2);
group3D.add(pointP);
registerInteractive(pointP, { title: "Point P", tooltip: "Drag to move P" });

// Reference Lines for P
const refMat = new THREE.LineDashedMaterial({color: 0x999999, dashSize: 0.2, gapSize: 0.1});
const refLineDrop = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), refMat);
const refLineAxis = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), refMat);
group3D.add(refLineDrop, refLineAxis);

// Virtual Plane Group
const virtGroup = new THREE.Group();
group3D.add(virtGroup);
const planeGeom = new THREE.PlaneGeometry(6, 4.8);
planeGeom.rotateY(Math.PI / 2); // Face +X
const virtMat = new THREE.MeshBasicMaterial({color: 0xdddddd, transparent: true, opacity: 0.6, side: THREE.DoubleSide, depthWrite: false});
const virtPlane = new THREE.Mesh(planeGeom, virtMat);
virtGroup.add(virtPlane);
const virtEdge = new THREE.LineSegments(new THREE.EdgesGeometry(planeGeom), new THREE.LineBasicMaterial({color: 0x000000}));
virtGroup.add(virtEdge);
// Virtual camera axes: y points up (0,1,0), x points parallel to world X (0,0,-1)
const virtY = new THREE.ArrowHelper(new THREE.Vector3(0,1,0), new THREE.Vector3(0,0,0), 2, 0x00aa00, 0.25, 0.15);
const virtX = new THREE.ArrowHelper(new THREE.Vector3(0,0,-1), new THREE.Vector3(0,0,0), 2, 0x00aa00, 0.25, 0.15);
virtGroup.add(virtY, virtX);
const pVirt = new THREE.Mesh(new THREE.SphereGeometry(0.1, 16, 16), new THREE.MeshBasicMaterial({color: 0x66ccff}));
const pVirtOutline = new THREE.Mesh(new THREE.SphereGeometry(0.1, 16, 16), new THREE.MeshBasicMaterial({color: 0x222222, side: THREE.BackSide}));
pVirtOutline.scale.setScalar(1.15);
pVirt.add(pVirtOutline);
virtGroup.add(pVirt);

// Physical Plane Group
const physGroup = new THREE.Group();
group3D.add(physGroup);
const physMat = new THREE.MeshBasicMaterial({color: 0x999999, transparent: true, opacity: 0.6, side: THREE.DoubleSide, depthWrite: false});
const physPlane = new THREE.Mesh(planeGeom, physMat);
physGroup.add(physPlane);
const physEdgeMat = new THREE.LineDashedMaterial({color: 0x000000, dashSize: 0.2, gapSize: 0.1});
const physEdge = new THREE.LineSegments(new THREE.EdgesGeometry(planeGeom), physEdgeMat);
physEdge.computeLineDistances();
physGroup.add(physEdge);
// Physical camera axes (inverted): y points down (0,-1,0), x points out (0,0,1)
const physY = new THREE.ArrowHelper(new THREE.Vector3(0,-1,0), new THREE.Vector3(0,0,0), 2, 0x00aa00, 0.25, 0.15);
const physX = new THREE.ArrowHelper(new THREE.Vector3(0,0,1), new THREE.Vector3(0,0,0), 2, 0x00aa00, 0.25, 0.15);
physGroup.add(physY, physX);
const pPhys = new THREE.Mesh(new THREE.SphereGeometry(0.1, 16, 16), new THREE.MeshBasicMaterial({color: 0x66ccff}));
const pPhysOutline = new THREE.Mesh(new THREE.SphereGeometry(0.1, 16, 16), new THREE.MeshBasicMaterial({color: 0x222222, side: THREE.BackSide}));
pPhysOutline.scale.setScalar(1.15);
pPhys.add(pPhysOutline);
physGroup.add(pPhys);

// Connection Ray
const rayMat = new THREE.LineDashedMaterial({color: 0x888888, dashSize: 0.2, gapSize: 0.1});
const rayLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), rayMat);
group3D.add(rayLine);

// Focal length arrows (offset to avoid axis overlap)
const arrowFvirt = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(0,-0.2,0.3), 3, 0xdd0000, 0.3, 0.15);
const arrowFphys = new THREE.ArrowHelper(new THREE.Vector3(-1,0,0), new THREE.Vector3(0,-0.2,0.3), 3, 0xdd0000, 0.3, 0.15);
group3D.add(arrowFvirt, arrowFphys);

// --- 2D Sensor Elements ---
const sensorGeom = new THREE.PlaneGeometry(6, 4.8);
const sensorMesh = new THREE.Mesh(sensorGeom, new THREE.MeshBasicMaterial({color: 0xffffff, depthWrite: false}));
group2D.add(sensorMesh);
const sensorEdge = new THREE.LineSegments(new THREE.EdgesGeometry(sensorGeom), new THREE.LineBasicMaterial({color: 0x000000, linewidth: 2}));
group2D.add(sensorEdge);
// Camera axes in 2D (origin center): x points left (-1,0,0), y points up (0,1,0)
const camX2d = new THREE.ArrowHelper(new THREE.Vector3(-1,0,0), new THREE.Vector3(0,0,0), 1.5, 0x00aa00, 0.2, 0.1);
const camY2d = new THREE.ArrowHelper(new THREE.Vector3(0,1,0), new THREE.Vector3(0,0,0), 1.5, 0x00aa00, 0.2, 0.1);
group2D.add(camX2d, camY2d);
// Image axes in 2D (origin bottom-left): n points right (1,0,0), m points up (0,1,0)
const imgX2d = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(-3, -2.4, 0), 1.5, 0x0000cc, 0.2, 0.1);
const imgY2d = new THREE.ArrowHelper(new THREE.Vector3(0,1,0), new THREE.Vector3(-3, -2.4, 0), 1.5, 0x0000cc, 0.2, 0.1);
group2D.add(imgX2d, imgY2d);
const p2d = new THREE.Mesh(new THREE.SphereGeometry(0.08, 16, 16), new THREE.MeshBasicMaterial({color: 0x66ccff}));
const p2dOutline = new THREE.Mesh(new THREE.SphereGeometry(0.08, 16, 16), new THREE.MeshBasicMaterial({color: 0x222222, side: THREE.BackSide}));
p2dOutline.scale.setScalar(1.15);
p2d.add(p2dOutline);
group2D.add(p2d);

// --- Interactions & Dragging ---
let isDragging = false;
const dragPlane = new THREE.Plane();
const intersection = new THREE.Vector3();

canvas.addEventListener('pointerdown', (e) => {
    if (document.getElementById('select-view').value === '2D Sensor View (b)') return; 
    const hit = window._firstInteractiveHit ? window._firstInteractiveHit(e) : null;
    if (hit && hit.object === pointP) {
        isDragging = true;
        controls.enabled = false;
        const camDir = new THREE.Vector3();
        camera.getWorldDirection(camDir).negate();
        dragPlane.setFromNormalAndCoplanarPoint(camDir, pointP.position);
    }
});
canvas.addEventListener('pointermove', (e) => {
    if (!isDragging) return;
    const rect = canvas.getBoundingClientRect();
    const ptr = new THREE.Vector2(((e.clientX - rect.left) / rect.width) * 2 - 1, -((e.clientY - rect.top) / rect.height) * 2 + 1);
    const rc = new THREE.Raycaster();
    rc.setFromCamera(ptr, camera);
    if (rc.ray.intersectPlane(dragPlane, intersection)) {
        const fVal = parseFloat(document.getElementById('slider-f').value);
        intersection.x = Math.max(fVal + 1, Math.min(15, intersection.x)); // Keep P in front of Virtual Plane
        intersection.y = Math.max(-8, Math.min(8, intersection.y));
        intersection.z = Math.max(-8, Math.min(8, intersection.z));
        pointP.position.copy(intersection);
        updatePositions();
    }
});
window.addEventListener('pointerup', () => {
    isDragging = false;
    controls.enabled = true;
});

// --- Labels ---
const allLabels = [];

function createLabel(text, posFn, viewTag, groupTag, options = {}) {
    const opts = Object.assign({ fontSize: '13px' }, options);
    const lbl = addLabel(text, new THREE.Vector3(), opts);
