createLabel('<b>p</b>', () => virtGroup.position.clone().add(pVirt.position), '3d', 'virt', { offset: [12, -12], fontSize: '15px' });
createLabel('<i>x</i>', () => virtGroup.position.clone().add(new THREE.Vector3(0, 0, -2.2)), '3d', 'virt', { offset: [-10, -10], color: '#009900' });
createLabel('<i>y</i>', () => virtGroup.position.clone().add(new THREE.Vector3(0, 2.2, 0)), '3d', 'virt', { offset: [10, 0], color: '#009900' });

// 3D Text (Physical group)
createLabel('Projection plane', () => new THREE.Vector3(physGroup.position.x, -2.6, 0), '3d', 'phys', { offset: [0, 10] });
createLabel('<i>f</i>', () => new THREE.Vector3(physGroup.position.x / 2, -0.2, 0.3), '3d', 'phys', { offset: [0, -15], color: '#cc0000' });
createLabel('<b>p</b>', () => physGroup.position.clone().add(pPhys.position), '3d', 'phys', { offset: [-12, 12], fontSize: '15px' });
createLabel('<i>x</i>', () => physGroup.position.clone().add(new THREE.Vector3(0, 0, 2.2)), '3d', 'phys', { offset: [10, 10], color: '#009900' });
createLabel('<i>y</i>', () => physGroup.position.clone().add(new THREE.Vector3(0, -2.2, 0)), '3d', 'phys', { offset: [10, 0], color: '#009900' });

// 2D Text
const Y2D = 100;
createLabel('Camera coordinates', () => new THREE.Vector3(1.5, Y2D + 1.5, 0), '2d', '2d', { offset: [0, -20], color: '#009900' });
createLabel('Image coordinates', () => new THREE.Vector3(-1.5, Y2D - 2.2, 0), '2d', '2d', { offset: [0, -10], color: '#0000cc' });
createLabel('<i>x</i>', () => new THREE.Vector3(-1.6, Y2D, 0), '2d', '2d', { offset: [-15, 15], color: '#009900' });
createLabel('<i>y</i>', () => new THREE.Vector3(0, Y2D + 1.6, 0), '2d', '2d', { offset: [15, 0], color: '#009900' });
createLabel('<i>n</i>', () => new THREE.Vector3(-1.4, Y2D - 2.4, 0), '2d', '2d', { offset: [0, 15], color: '#0000cc' });
createLabel('<i>m</i>', () => new THREE.Vector3(-3, Y2D - 0.8, 0), '2d', '2d', { offset: [15, 0], color: '#0000cc' });
createLabel('(0,0)', () => new THREE.Vector3(-3, Y2D - 2.4, 0), '2d', '2d', { offset: [-20, 15], color: '#0000cc' });
createLabel('(0,0)', () => new THREE.Vector3(0, Y2D, 0), '2d', '2d', { offset: [20, 15], color: '#009900' });
createLabel('Virtual camera plane', () => new THREE.Vector3(0, Y2D - 2.8, 0), '2d', '2d', { offset: [0, 0] });
createLabel('<b>p</b>', () => p2d.position.clone().add(new THREE.Vector3(0, Y2D, 0)), '2d', '2d', { offset: [15, -15], fontSize: '15px' });

// --- Logic & Updates ---
function updatePositions() {
    const fVal = parseFloat(document.getElementById('slider-f').value);

    virtGroup.position.set(fVal, 0, 0);
    physGroup.position.set(-fVal, 0, 0);
    arrowFvirt.setLength(fVal, 0.3, 0.15);
    arrowFphys.setLength(fVal, 0.3, 0.15);

    const px = pointP.position.x;
    const py = pointP.position.y;
    const pz = pointP.position.z;

    const v_y = px !== 0 ? (py * fVal / px) : 0;
    const v_z = px !== 0 ? (pz * fVal / px) : 0;
    const p_y = px !== 0 ? (py * (-fVal) / px) : 0;
    const p_z = px !== 0 ? (pz * (-fVal) / px) : 0;

    pVirt.position.set(0, v_y, v_z);
    pPhys.position.set(0, p_y, p_z);

    // In 2D View, Textbook X (Three.js -z) maps to horizontal. Since Camera x points left, 
    // a positive Textbook X should be on the left.
    // Three.z = -Textbook X. So we use Three.z directly for horizontal position in 2D.
    p2d.position.set(v_z, v_y, 0.01);

    // Reference lines for P in 3D
    refLineDrop.geometry.setFromPoints([pointP.position, new THREE.Vector3(px, 0, pz)]);
    refLineDrop.computeLineDistances();
    refLineAxis.geometry.setFromPoints([new THREE.Vector3(px, 0, pz), new THREE.Vector3(px, 0, 0)]);
    refLineAxis.computeLineDistances();

    const projMode = document.getElementById('select-proj').value;
    const endPt = new THREE.Vector3();
    if (projMode === 'Both' || projMode === 'Physical (Inverted)') {
        endPt.set(-fVal, p_y, p_z);
    } else {
        endPt.set(0, 0, 0);
    }
    rayLine.geometry.setFromPoints([pointP.position, endPt]);
    rayLine.computeLineDistances();

    updateLabels();
}

function updateVisibility() {
    const view = document.getElementById('select-view').value;
    const projMode = document.getElementById('select-proj').value;

    if (view === '2D Sensor View (b)') {
        group3D.visible = false;
        group2D.visible = true;
    } else {
        group3D.visible = true;
        group2D.visible = false;
        virtGroup.visible = (projMode === 'Both' || projMode === 'Virtual (Upright)');
        physGroup.visible = (projMode === 'Both' || projMode === 'Physical (Inverted)');
        arrowFvirt.visible = virtGroup.visible;
        arrowFphys.visible = physGroup.visible;
        rayLine.visible = true;
    }
}

function updateLabels() {
    const view = document.getElementById('select-view').value;
    const projMode = document.getElementById('select-proj').value;

    allLabels.forEach(obj => {
        let isVis = false;
        if (view === '2D Sensor View (b)') {
            isVis = (obj.viewTag === '2d');
        } else {
            if (obj.viewTag === '3d') {
                if (obj.groupTag === 'virt') isVis = (projMode === 'Both' || projMode === 'Virtual (Upright)');
                else if (obj.groupTag === 'phys') isVis = (projMode === 'Both' || projMode === 'Physical (Inverted)');
                else isVis = true;
            }
        }

        // Push labels far away when hidden so _syncLabels automatically ignores them
        if (isVis) {
            obj.lbl.pos.copy(obj.posFn());
        } else {
            obj.lbl.pos.set(99999, 99999, 99999);
        }
    });
}

let lastView = null;
function onStateChange() {
    updateVisibility();
    updatePositions();

    const view = document.getElementById('select-view').value;
    if (view !== lastView) {
        if (view === '2D Sensor View (b)') {
            setCameraView({ projection: 'orthographic', axisScreenAngles: null, heightFraction: 0.7, target: [0, Y2D, 0] });
        } else {
            setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.65, target: [2, 0, 0] });
        }
        lastView = view;
    }
}

// --- Guided Demo Steps ---
const steps = [
  {
    title: "Pinhole Projection",
    narration: "A 3D scene point P projects through the pinhole at the origin onto sensor planes. Both physical (behind) and virtual (in front) planes exist at distance f.",
    state: { panelView: "3D Camera Model (a)", projectionMode: "Both", focalLength: 3 }
  },
  {
    title: "Virtual Plane Convention",
    narration: "The physical sensor receives an inverted image. The virtual plane convention models a sensor in front of the pinhole, preserving projective geometry while keeping the image upright.",
    state: { panelView: "3D Camera Model (a)", projectionMode: "Virtual (Upright)", focalLength: 3 }
  },
  {
    title: "Focal Length",
    narration: "Increasing the focal length f moves the planes outward. The projection rays diverge further, mapping P to a larger coordinate on the plane (magnification).",
    state: { panelView: "3D Camera Model (a)", projectionMode: "Virtual (Upright)", focalLength: 5 }
  },
  {
    title: "2D Image Coordinates",
    narration: "On the 2D sensor, continuous camera coordinates (x,y) originate at the optical center, while discrete image pixel indices (n,m) originate at the corner.",
    state: { panelView: "2D Sensor View (b)", projectionMode: "Virtual (Upright)", focalLength: 3 }
  }
];

function goToStep(idx) {
    const step = steps[idx];
    document.getElementById('select-view').value = step.state.panelView;
    document.getElementById('select-proj').value = step.state.projectionMode;
    document.getElementById('slider-f').value = step.state.focalLength;

    document.getElementById('step-desc').innerHTML = `<b>${step.title}</b><br/>${step.narration}`;

    for(let i=0; i<4; i++) {
        const btn = document.getElementById(`btn-step-${i}`);
        if (i === idx) btn.classList.add('active');
        else btn.classList.remove('active');
    }
    onStateChange();
}

for(let i=0; i<4; i++) {
    document.getElementById(`btn-step-${i}`).addEventListener('click', () => goToStep(i));
}

document.getElementById('slider-f').addEventListener('input', updatePositions);
document.getElementById('select-proj').addEventListener('change', () => { updateVisibility(); updatePositions(); });
document.getElementById('select-view').addEventListener('change', onStateChange);

onStateChange();
// @FIGURE_CODE_END

